class Policy:
    # Changed: prioritize untried tasks, then lowest-scoring tried tasks, to find unsolved ones faster.
    def __init__(self):
        self.scores = {}
        self.tried = set()

    def pick(self, keys, round_index):
        # Prefer tasks we haven't tried yet
        untried = [k for k in keys if k not in self.tried]
        if untried:
            return untried[0]
        # Among tried, pick the one with lowest score (most likely unsolved)
        return min(keys, key=lambda k: self.scores.get(k, 0))

    def record(self, task_id, score):
        self.tried.add(task_id)
        self.scores[task_id] = score
