class Policy:
    # Changed: prioritize untried/low-score tasks over round-robin to avoid wasting rollouts on solved tasks.
    def __init__(self):
        self.scores = {}  # task_id -> best score seen

    def pick(self, keys, round_index):
        # Filter to tasks we haven't solved (score < 1.0)
        unsolved = [k for k in keys if self.scores.get(k, 0) < 1.0]
        if not unsolved:
            # All solved in this shard, just pick first
            return keys[0]

        # Among unsolved, prefer ones we've never tried (unknown score)
        untried = [k for k in unsolved if k not in self.scores]
        if untried:
            # Pick the first untried (deterministic, but could randomize)
            return untried[0]

        # All unsolved have been tried; pick the one with lowest score
        # (most room for improvement)
        return min(unsolved, key=lambda k: self.scores[k])

    def record(self, task_id, score):
        # Keep the best score (since we might retry and improve)
        if task_id not in self.scores or score > self.scores[task_id]:
            self.scores[task_id] = score
